namespace CourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public string Id { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Instructor { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public string CourseId { get; set; } = string.Empty;
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and software systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and communication studies." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Exploration of past events, cultures, and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, data structures, and object-oriented principles.", DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Instructor = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of industry experience at major tech companies and has been teaching introductory CS courses for 8 years.", IsFeatured = true },
        new() { Id = "CS301", Title = "Data Structures & Algorithms", Description = "Advanced study of data structures including trees, graphs, and hash tables. Algorithm design and complexity analysis.", DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", Instructor = "Dr. James Park", InstructorBio = "Dr. Park's research focuses on algorithm optimization. He holds a PhD from MIT and has published over 40 papers." },
        new() { Id = "CS410", Title = "Machine Learning", Description = "Introduction to machine learning concepts: supervised and unsupervised learning, neural networks, and model evaluation.", DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 4, Schedule = "Tue/Thu 1:00–2:15 PM", Instructor = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez leads the university's AI research lab and has contributed to several open-source ML frameworks.", IsFeatured = true },
        new() { Id = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science.", DepartmentId = "math", DepartmentName = "Mathematics", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Instructor = "Dr. Alan Foster", InstructorBio = "Dr. Foster specializes in applied mathematics and has authored two widely-used textbooks on linear algebra." },
        new() { Id = "MATH301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", DepartmentId = "math", DepartmentName = "Mathematics", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM", Instructor = "Dr. Lisa Wang", InstructorBio = "Dr. Wang is a biostatistician whose work bridges mathematics and public health research.", IsFeatured = true },
        new() { Id = "ENG101", Title = "College Writing", Description = "Develop critical thinking and writing skills through essay composition, research methods, and peer review.", DepartmentId = "eng", DepartmentName = "English", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Instructor = "Prof. Michael Torres", InstructorBio = "Prof. Torres is a published novelist and essayist who brings creative writing techniques into academic composition." },
        new() { Id = "ENG250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, exploring themes of identity and social change.", DepartmentId = "eng", DepartmentName = "English", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", Instructor = "Dr. Karen Phillips", InstructorBio = "Dr. Phillips is a Pulitzer-nominated critic specializing in 20th-century American fiction." },
        new() { Id = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", DepartmentId = "phys", DepartmentName = "Physics", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Lab Thu 2:00–4:00 PM", Instructor = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist with expertise in materials science and quantum optics." },
        new() { Id = "PHYS301", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory.", DepartmentId = "phys", DepartmentName = "Physics", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM", Instructor = "Dr. Elena Novak", InstructorBio = "Dr. Novak's research in quantum computing has been funded by multiple national science grants.", IsFeatured = true },
        new() { Id = "HIST101", Title = "World History to 1500", Description = "Survey of major civilizations, cultural exchanges, and turning points in human history before the modern era.", DepartmentId = "hist", DepartmentName = "History", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Instructor = "Dr. David Okafor", InstructorBio = "Dr. Okafor is an archaeologist and historian whose fieldwork spans three continents." },
        new() { Id = "HIST220", Title = "Modern European History", Description = "Europe from the Enlightenment through the 21st century: revolutions, wars, and the formation of the EU.", DepartmentId = "hist", DepartmentName = "History", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Instructor = "Dr. Claire Dubois", InstructorBio = "Dr. Dubois is a Franco-American historian and former consultant to the European Parliament archives." },
    ];

    private readonly List<EnrollmentRequest> _enrollments = [];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetCourses(string? search = null, string? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(search, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request) =>
        _enrollments.Add(request);
}

